<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\SmtpOutboundConfigLoginVO;

trait SmtpOutboundConfigLoginAccessor
{
    private SmtpOutboundConfigLoginVO $_login;
    public function getLogin(): string
    {
        return $this->_login->value();
    }
    public function login(): SmtpOutboundConfigLoginVO
    {
        return $this->_login;
    }
    public function isLoginChanged(?self $original = null): bool
    {
        return !$this->_login->equals($original?->_login);
    }
    public function withLogin(SmtpOutboundConfigLoginVO|string $login): self
    {
        $copy = clone $this;
        $copy->_login = SmtpOutboundConfigLoginVO::from($login);
        return $copy;
    }
}
